import ghidra.app.script.GhidraScript;
import ghidra.app.util.PseudoInstruction;
import ghidra.program.model.lang.*;
import ghidra.program.model.mem.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import java.nio.file.*;import java.util.*;import java.math.BigInteger;import java.security.*;import com.google.gson.*;
public class C6000ParallelPeerAnalyzerTest extends GhidraScript {
 long n(JsonObject r,String key){return r.get(key).getAsLong();}
 String sha(byte[] value)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}
 void equal(Object expected,Object actual,String message){if(!Objects.equals(expected,actual))throw new AssertionError(message+" expected="+expected+" actual="+actual);}
 void create(long pc)throws Exception{var at=toAddr(pc);var context=new ProcessorContextImpl(currentProgram.getLanguage());var value=currentProgram.getProgramContext().getRegisterValue(currentProgram.getLanguage().getContextBaseRegister(),at);if(value!=null)context.setRegisterValue(value);var memory=new DumbMemBufferImpl(currentProgram.getMemory(),at);var prototype=currentProgram.getLanguage().parse(memory,context,false);currentProgram.getListing().createInstruction(at,prototype,memory,context,0);}
 protected void run()throws Exception{
  var args=getScriptArgs();var rows=JsonParser.parseString(Files.readString(Paths.get(args[0]))).getAsJsonArray();var folder=Paths.get(args[1]);Files.createDirectories(folder);c6000.C6000PacketContext.prime(currentProgram,monitor);var anchors=new JsonArray();int expected=0;long source=0x1000,end=0x1000+rows.size()*0x100;
  for(var element:rows){var row=element.getAsJsonObject();String name=row.get("name").getAsString();long at=n(row,"anchor"),peer=n(row,"peer"),base=n(row,"base");currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_flow_delay"),toAddr(at),toAddr(at),BigInteger.ZERO);create(at);long ownerEnd=at+currentProgram.getListing().getInstructionAt(toAddr(at)).getLength()-1;if(name.equals("anchor_partial_owner"))ownerEnd=at+1;if(name.equals("already_defined"))ownerEnd=peer+3;if(name.equals("partial_owner")||name.equals("defined_partial_bridge"))ownerEnd=peer+1;currentProgram.getFunctionManager().createFunction("peer_"+name,toAddr(base),new AddressSet(toAddr(base),toAddr(ownerEnd)),SourceType.USER_DEFINED);
   if(name.equals("late_data"))createData(toAddr(peer+4),ghidra.program.model.data.DWordDataType.dataType);if(name.equals("data_start"))createData(toAddr(peer),ghidra.program.model.data.DWordDataType.dataType);if(name.equals("data_suffix"))createData(toAddr(peer+3),ghidra.program.model.data.ByteDataType.dataType);if(name.equals("instruction_suffix")){currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_is16"),toAddr(peer+2),toAddr(peer+2),BigInteger.ONE);create(peer+2);}if(name.equals("foreign_owner"))currentProgram.getFunctionManager().createFunction("different_peer_owner",toAddr(peer),new AddressSet(toAddr(peer),toAddr(peer+3)),SourceType.USER_DEFINED);if(name.equals("stale_context"))currentProgram.getProgramContext().setValue(currentProgram.getRegister("c_is16"),toAddr(peer),toAddr(peer),BigInteger.ZERO);if(name.equals("already_defined")||name.equals("defined_partial_bridge"))create(peer);
   if(name.equals("annotations")){setEOLComment(toAddr(peer),"keep undefined peer comment");setPlateComment(toAddr(peer),"keep undefined peer plate");currentProgram.getSymbolTable().createLabel(toAddr(peer),"annotated_peer",SourceType.USER_DEFINED);currentProgram.getReferenceManager().addMemoryReference(toAddr(peer),toAddr(base+128),RefType.DATA,SourceType.USER_DEFINED,0);currentProgram.getReferenceManager().addMemoryReference(toAddr(base+128),toAddr(peer),RefType.DATA,SourceType.USER_DEFINED,0);}
   if(name.equals("nested_window")){var cls=Class.forName("c6000.C6000DelaySlots$Reader");var constructor=cls.getDeclaredConstructor(ghidra.program.model.listing.Program.class);constructor.setAccessible(true);var reader=constructor.newInstance(currentProgram);var method=cls.getDeclaredMethod("window",ghidra.program.model.listing.Instruction.class,ghidra.util.task.TaskMonitor.class);method.setAccessible(true);equal(null,method.invoke(reader,currentProgram.getListing().getInstructionAt(toAddr(at)),monitor),"nested full window still refuses");}
   byte[] raw=new byte[currentProgram.getListing().getInstructionAt(toAddr(at)).getLength()];currentProgram.getMemory().getBytes(toAddr(at),raw);var anchor=new JsonObject();anchor.addProperty("address",at);anchor.addProperty("allowed_end",n(row,"allowed_end"));anchor.addProperty("expected_bytes",HexFormat.of().formatHex(raw));anchors.add(anchor);expected+=row.get("expected").getAsInt()+(name.equals("bound_cut")?1:0);
  }

  var roots=new AddressSet();for(var element:rows)roots.add(toAddr(n(element.getAsJsonObject(),"anchor")));
  var analyzer=new c6000.C6000CompactPacketTailAnalyzer();
  var beforeFunctions=new TreeMap<String,String>();var functions=currentProgram.getFunctionManager().getFunctions(true);while(functions.hasNext()){var f=functions.next();beforeFunctions.put(f.getEntryPoint().toString(),f.getName()+"|"+f.getBody()+"|"+f.getPrototypeString(true,false));}
  var beforeContext=new ArrayList<String>();for(var element:rows){long peer=n(element.getAsJsonObject(),"peer");beforeContext.add(String.valueOf(currentProgram.getProgramContext().getRegisterValue(currentProgram.getLanguage().getContextBaseRegister(),toAddr(peer))));}
  var beforeInstructions=new TreeMap<String,String>();var ii=currentProgram.getListing().getInstructions(true);while(ii.hasNext()){var i=ii.next();beforeInstructions.put(i.getAddress().toString(),i+"|"+i.getLength()+"|"+i.getFlowOverride()+"|"+i.getFallThrough()+"|"+i.getDelaySlotDepth());}
  var beforeRefs=new TreeSet<String>();var sources=currentProgram.getReferenceManager().getReferenceSourceIterator(currentProgram.getMemory().getAllInitializedAddressSet(),true);while(sources.hasNext())for(var ref:currentProgram.getReferenceManager().getReferencesFrom(sources.next()))beforeRefs.add(ref.toString()+"|"+ref.getSource()+"|"+ref.isPrimary()+"|"+ref.getSymbolID());
  long countBefore=currentProgram.getListing().getNumInstructions();
  if(!analyzer.added(currentProgram,roots,monitor,new ghidra.app.util.importer.MessageLog()))throw new AssertionError("analyzer failed");
  equal((long)expected,currentProgram.getListing().getNumInstructions()-countBefore,"analyzer created count");
  for(var element:rows){var row=element.getAsJsonObject();long peer=n(row,"peer"),base=n(row,"base");String name=row.get("name").getAsString();if(row.get("expected").getAsInt()>0||name.equals("bound_cut")){var instruction=currentProgram.getListing().getInstructionAt(toAddr(peer));if(instruction==null)throw new AssertionError("missing peer "+name);equal((int)n(row,"width"),instruction.getLength(),"physical peer width");if(currentProgram.getListing().getInstructionAt(toAddr(peer+instruction.getLength()))!=null)throw new AssertionError("ordinary flow followed "+name);}
   else if(!name.equals("already_defined")&&!name.equals("defined_partial_bridge")&&currentProgram.getListing().getInstructionAt(toAddr(peer))!=null)throw new AssertionError("conflicting peer overwritten "+name);
   if(name.equals("annotations")){equal("keep undefined peer comment",getEOLComment(toAddr(peer)),"EOL preserved");equal("keep undefined peer plate",getPlateComment(toAddr(peer)),"plate preserved");equal("annotated_peer",currentProgram.getSymbolTable().getPrimarySymbol(toAddr(peer)).getName(),"label preserved");}
   if(name.equals("defined_partial_bridge")&&currentProgram.getListing().getInstructionAt(toAddr(peer+4))!=null)throw new AssertionError("recovered beyond partial-owned defined bridge");
   if(name.equals("stale_context"))equal(BigInteger.ZERO,currentProgram.getProgramContext().getValue(currentProgram.getRegister("c_is16"),toAddr(peer),false),"stale context retained");
  }

  var afterInstructions=new TreeMap<String,String>();ii=currentProgram.getListing().getInstructions(true);while(ii.hasNext()){var i=ii.next();afterInstructions.put(i.getAddress().toString(),i+"|"+i.getLength()+"|"+i.getFlowOverride()+"|"+i.getFallThrough()+"|"+i.getDelaySlotDepth());}for(var row:beforeInstructions.entrySet())equal(row.getValue(),afterInstructions.get(row.getKey()),"original instruction retention");
  var afterRefs=new TreeSet<String>();sources=currentProgram.getReferenceManager().getReferenceSourceIterator(currentProgram.getMemory().getAllInitializedAddressSet(),true);while(sources.hasNext())for(var ref:currentProgram.getReferenceManager().getReferencesFrom(sources.next()))afterRefs.add(ref.toString()+"|"+ref.getSource()+"|"+ref.isPrimary()+"|"+ref.getSymbolID());equal(true,afterRefs.containsAll(beforeRefs),"original reference retention");
  var afterFunctions=new TreeMap<String,String>();functions=currentProgram.getFunctionManager().getFunctions(true);while(functions.hasNext()){var f=functions.next();afterFunctions.put(f.getEntryPoint().toString(),f.getName()+"|"+f.getBody()+"|"+f.getPrototypeString(true,false));}equal(beforeFunctions,afterFunctions,"function metadata/body retention");
  int rowIndex=0;for(var element:rows){long peer=n(element.getAsJsonObject(),"peer");equal(beforeContext.get(rowIndex++),String.valueOf(currentProgram.getProgramContext().getRegisterValue(currentProgram.getLanguage().getContextBaseRegister(),toAddr(peer))),"decode context retention");}
  long after=currentProgram.getModificationNumber();if(!analyzer.added(currentProgram,roots,monitor,new ghidra.app.util.importer.MessageLog()))throw new AssertionError("repeat analyzer failed");equal(after,currentProgram.getModificationNumber(),"idempotent analyzer");
  var cancelled=new ghidra.util.task.TaskMonitorAdapter(true);cancelled.cancel();boolean stopped=false;try{analyzer.added(currentProgram,roots,cancelled,new ghidra.app.util.importer.MessageLog());}catch(ghidra.util.exception.CancelledException wanted){stopped=true;}equal(true,stopped,"cancellation propagated");equal(after,currentProgram.getModificationNumber(),"cancellation unchanged");
  byte[] packet=new byte[32];currentProgram.getMemory().getBytes(toAddr(0x1000),packet);var overlay=currentProgram.getMemory().createInitializedBlock("peer_overlay",toAddr(0x1000),32,(byte)0,monitor,true);var overlayAt=overlay.getStart();currentProgram.getMemory().setBytes(overlayAt,packet);var overlayContext=new ProcessorContextImpl(currentProgram.getLanguage());var overlayMemory=new DumbMemBufferImpl(currentProgram.getMemory(),overlayAt);var overlayPrototype=currentProgram.getLanguage().parse(overlayMemory,overlayContext,false);currentProgram.getListing().createInstruction(overlayAt,overlayPrototype,overlayMemory,overlayContext,0);long overlayToken=currentProgram.getModificationNumber();if(!analyzer.added(currentProgram,new AddressSet(overlayAt),monitor,new ghidra.app.util.importer.MessageLog()))throw new AssertionError("overlay analysis failed");equal(overlayToken,currentProgram.getModificationNumber(),"overlay must not use default-space proof");
  println("C6000_PARALLEL_PEER_ANALYZER_OK cases="+rows.size()+" created="+expected+" cancellation=true overlay=true");
 }
}
